        { type: "qcm", q: "Which Breton knight, named constable in 1370, leads the reconquest for Charles V?", c: "Bertrand du Guesclin", w: ["Olivier de Clisson", "John of Dunois", "Gilles de Rais"], e: "A poor minor Breton noble, he becomes head of the king's army. Olivier de Clisson, his companion, succeeds him as constable in 1380." },
        { type: "qcm", q: "Which king, struck by fits of madness from 1392, reigns from 1380 to 1422?", c: "Charles VI", w: ["Charles V", "Charles VII", "Louis XI"], e: "His fits alternate with periods of lucidity. Meanwhile, the princes of his family quarrel over power." },
        { type: "qcm", q: "Which rivalry divides the kingdom of France under Charles VI?", c: "Armagnacs and Burgundians", w: ["Guelphs and Ghibellines", "Lancaster and York", "Huguenots and Catholics"], e: "It pits the supporters of the duke of Orléans, son-in-law of the count of Armagnac, against those of the duke of Burgundy. The English take advantage." },
        { type: "qcm", q: "Which king of England wins the victory of Agincourt?", c: "Henry V", w: ["Edward III", "Richard II", "Henry VI"], e: "His troops, tired and fewer in number, take advantage of narrow, muddy ground. The archers do the rest." },
        { type: "tf", q: "The treaty of Troyes provides that Henry V of England inherits the crown of France.", a: true, e: "Charles VI disinherits his own son, the dauphin Charles, accused of having been involved in the murder of John the Fearless. The treaty deeply divides the kingdom." },
        { type: "tf", q: "At Agincourt, the French cavalry easily scatters the English archers.", a: false, e: "On the contrary: the horses bog down in the mud and the heavy armour tires the men. The French suffer very heavy losses." },
        { type: "order", q: "Put these events of the reigns of Charles V and Charles VI in order.", items: [{ t: "Charles V becomes king", y: "1364" }, { t: "Du Guesclin becomes constable", y: "1370" }, { t: "Charles VI loses his reason", y: "1392" }, { t: "Battle of Agincourt", y: "25 October 1415" }] },
        { type: "match", q: "Match each figure of the period to his or her role or fate.", pairs: [["Charles V", "Bastille and Louvre library"], ["John the Fearless", "Duke of Burgundy assassinated in 1419"], ["Louis of Orléans", "King's brother, assassinated in 1407"], ["Catherine of Valois", "Daughter of Charles VI, wife of Henry V"]] },
        { type: "year", q: "In which year is the treaty of Troyes signed?", y: 1420, min: 1340, max: 1460, tol: 1, e: "Signed on 21 May 1420, it is applied only in the regions held by the Anglo-Burgundians. Henry V dies in August 1422, shortly before Charles VI, and the dauphin Charles refuses to step aside." }
